import{_ as t,c as s,o as e,a3 as a}from"./chunks/framework.CoV49S2T.js";const u=JSON.parse('{"title":"macOS Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"guide/permissions.md","filePath":"guide/permissions.md","lastUpdated":1787284674000}'),o={name:"guide/permissions.md"};function n(r,i,l,p,c,h){return e(),s("div",null,[...i[0]||(i[0]=[a(`<h1 id="macos-permissions" tabindex="-1">macOS Permissions <a class="header-anchor" href="#macos-permissions" aria-label="Permalink to &quot;macOS Permissions&quot;">​</a></h1><p>ClipboxAI may request a few macOS permissions to provide the best experience. This page explains what each permission is for and how to manage it.</p><h2 id="clipboard-automation" tabindex="-1">Clipboard / Automation <a class="header-anchor" href="#clipboard-automation" aria-label="Permalink to &quot;Clipboard / Automation&quot;">​</a></h2><p>To capture your clipboard in the background and paste results back, ClipboxAI uses macOS Automation access.</p><p><strong>What it&#39;s used for</strong>: reading the current pasteboard when you copy, and writing results back when you run an action.</p><p><strong>Manage</strong>: <strong>System Settings → Privacy &amp; Security → Automation</strong> → enable <strong>ClipboxAI</strong>.</p><p>Grant access when prompted during first launch. You can manage or revoke it at any time.</p><h2 id="accessibility-optional" tabindex="-1">Accessibility (optional) <a class="header-anchor" href="#accessibility-optional" aria-label="Permalink to &quot;Accessibility (optional)&quot;">​</a></h2><p>Some builds use Accessibility to provide global keyboard shortcuts and to activate the history panel from anywhere.</p><p><strong>What it&#39;s used for</strong>: opening the history panel and running actions via hotkeys, even when the app isn&#39;t focused.</p><p><strong>Manage</strong>: <strong>System Settings → Privacy &amp; Security → Accessibility</strong> → enable <strong>ClipboxAI</strong>.</p><h2 id="notifications-optional" tabindex="-1">Notifications (optional) <a class="header-anchor" href="#notifications-optional" aria-label="Permalink to &quot;Notifications (optional)&quot;">​</a></h2><p>ClipboxAI may show notifications when a long-running action completes or needs attention.</p><p><strong>What it&#39;s used for</strong>: alerting you when an action finishes or when configuration is required.</p><p><strong>Manage</strong>: <strong>System Settings → Notifications</strong> → <strong>ClipboxAI</strong>.</p><h2 id="full-disk-access-optional" tabindex="-1">Full Disk Access (optional) <a class="header-anchor" href="#full-disk-access-optional" aria-label="Permalink to &quot;Full Disk Access (optional)&quot;">​</a></h2><p>Not required for normal use. Only needed if you want the app to read clips from system-protected locations.</p><p><strong>Manage</strong>: <strong>System Settings → Privacy &amp; Security → Full Disk Access</strong>.</p><p>This permission is optional and only needed in advanced scenarios.</p><h2 id="resetting-a-permission-with-terminal" tabindex="-1">Resetting a permission with Terminal <a class="header-anchor" href="#resetting-a-permission-with-terminal" aria-label="Permalink to &quot;Resetting a permission with Terminal&quot;">​</a></h2><p>If a permission dialog was dismissed or the state is inconsistent, you can reset macOS permission prompts using <code>tccutil</code>:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Reset automation/accessibility prompts for ClipboxAI</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tccutil</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> reset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> All</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> com.w3cub.clipboard</span></span></code></pre></div><p>After running <code>tccutil</code>, restart the app and trigger the feature again to be reprompted.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><ul><li>If clipboard history doesn&#39;t capture copies, check the <strong>Automation</strong> permission is granted.</li><li>If global shortcuts don&#39;t work, check the <strong>Accessibility</strong> permission.</li><li>After changing permissions, always quit and reopen ClipboxAI for changes to take effect.</li></ul><p>For more help, visit the <a href="/guide/troubleshooting.html">Troubleshooting guide</a>.</p>`,26)])])}const g=t(o,[["render",n]]);export{u as __pageData,g as default};
